<template><section><header class="page-head"><div><p class="eyebrow">WORKBENCH</p><h2>物业工作台</h2><p>掌握报修、收费和社区公告的最新动态。</p></div><el-button type="primary" @click="load">刷新数据</el-button></header><div class="stat-grid"><StatCard label="待处理工单" :value="summary.pending_repairs" hint="需要物业跟进"/><StatCard label="本月已收费用" :value="`¥${Number(summary.monthly_paid||0).toFixed(2)}`" hint="支付宝沙箱模拟数据"/><StatCard label="最新公告" :value="summary.announcements?.length||0" hint="近期开启阅读"/></div><section class="dashboard-block"><h3>最新公告</h3><AnnouncementCard v-for="v in summary.announcements" :key="v.id" :announcement="v" @open="open"/><EmptyState v-if="!summary.announcements?.length"/></section></section></template><script setup lang="ts">import{reactive,onMounted}from'vue';import{request}from'../utils/request';import type{Announcement}from'../types';import StatCard from'../components/common/StatCard.vue';import AnnouncementCard from'../components/common/AnnouncementCard.vue';import EmptyState from'../components/common/EmptyState.vue';const summary=reactive<{pending_repairs:number;monthly_paid:number;announcements:Announcement[]}>({pending_repairs:0,monthly_paid:0,announcements:[]});async function load(){Object.assign(summary,await request('/dashboard/summary'))};function open(id:number){location.hash=`#/announcements?open=${id}`};onMounted(load)</script>
